-- Venue Live Guest "Perayaan Tahun Baru Nyepi". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara nyepi), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'nyepi', 'Tahun Baru Nyepi (panggung Bali)', 'nyepi', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 118, 'center 38%',
  $t${"name":"Nyepi","orn":"diamond","ui":{"ivory":"#FBF3E2","white":"#FFFFFF","soft":"#EEDFF2","soft2":"#C9A8D8","accent":"#5B2A86","deep":"#2E1347","ink":"#2A1636","mute":"#7A6488","line":"#DCC8E6","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#FFFAF0","ink":"#2A1636","accent":"#5B2A86","gold":"#C9A227","leaf":"#EEDFF2","hbg":"rgba(251,243,226,.94)","hline":"#C9A8D8","motif":"diamond"},"hud":{"bg":"rgba(46,19,71,.86)","acc":"#F2D98A","on":"#2A1636"},"scr":{"wine":"#2E1347","veil":"251,243,226"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'nyepi');
update public.live_venues set decor = $d${"planter":{"url":"/assets/live-decor/nyepi/planter.webp","w":8,"x":0,"z":-7},"bush":{"url":"/assets/live-decor/nyepi/bush.webp","w":8,"x":0,"z":3},"lamp":{"url":"/assets/live-decor/nyepi/lamp.webp","w":1.5,"x":3.4,"z":-12,"mirror":true},"rope":{"url":"/assets/live-decor/nyepi/rope.webp","w":1.5,"x":3.4,"z":-2,"mirror":true},"speakers":{"url":"/assets/live-decor/nyepi/speakers.webp","w":2.4},"balloons":{"url":"/assets/live-decor/nyepi/balloons.webp","w":8,"x":0,"z":-17},"stall_snacks":{"url":"/assets/live-decor/nyepi/stall_snacks.webp","w":2.6},"stall_candy":{"url":"/assets/live-decor/nyepi/stall_candy.webp","w":2.2},"stall_drinks":{"url":"/assets/live-decor/nyepi/stall_drinks.webp","w":4.8},"photobooth":{"url":"/assets/live-decor/nyepi/photobooth.webp","w":5.6},"claw":{"url":"/assets/live-decor/nyepi/claw.webp","w":4.4},"arch":{"url":"/assets/live-decor/nyepi/arch.webp"},"fountain":{"url":"/assets/live-decor/nyepi/fountain.webp","w":5.8},"sign":{"url":"/assets/live-decor/nyepi/sign.webp","w":2.0},"easel":{"url":"/assets/live-decor/nyepi/easel.webp","w":2.8,"x":4.6,"z":8.2},"table":{"url":"/assets/live-decor/nyepi/table.webp"},"banner":{"url":"/assets/live-decor/nyepi/banner.webp","w":1.6},"gifts":{"url":"/assets/live-decor/nyepi/gifts.webp","w":1.5,"x":3.4,"z":-22,"mirror":true},"av_host":{"url":"/assets/live-decor/nyepi/av_host.webp","name":"Bli Udeng Marun"},"av_l1":{"url":"/assets/live-decor/nyepi/av_l1.webp","name":"Bli Udeng Marun"},"av_l2":{"url":"/assets/live-decor/nyepi/av_l2.webp","name":"Si Kacamata Udeng"},"av_l3":{"url":"/assets/live-decor/nyepi/av_l3.webp","name":"Bli Udeng Putih"},"av_l4":{"url":"/assets/live-decor/nyepi/av_l4.webp","name":"Bli Batik Hitam"},"av_p1":{"url":"/assets/live-decor/nyepi/av_p1.webp","name":"Mbok Kebaya Krem"},"av_p2":{"url":"/assets/live-decor/nyepi/av_p2.webp","name":"Mbak Hijab Krem"},"av_p3":{"url":"/assets/live-decor/nyepi/av_p3.webp","name":"Mbok Kebaya Marun"}}$d$::jsonb, background_url = '/assets/live-decor/nyepi/painting.webp', active = true, updated_at = now() where key = 'nyepi';
